---@class UIFightReardsNode
local UIFightReardsNode = Class("UIFightReardsNode")

function UIFightReardsNode:__init() 
    self._data = nil
    self._goSize = nil
    self._isFillTitle = false
end

function UIFightReardsNode:__delete()
    self._data = nil
    self._goSize = nil
    self._isFillTitle = nil 
end

function UIFightReardsNode:Awake()
end

function UIFightReardsNode:Start()
end

function UIFightReardsNode:Refersh(data, size, isFillTitle)
    if not data then
        return
    end
    self._data = checkTable(data)
    self._size = size
    if isFillTitle then
        self._isFillTitle = true
    else
        self._isFillTitle = false
    end

    self:FillReards()
end

function UIFightReardsNode:RefershSpacing(num)
    local group = self.Root.transform:GetComponent(typeof(HorizontalLayoutGroup))
    if group then
        group.spacing = checkNumber(num)
    end
end

function UIFightReardsNode:FillReards()
    local count = table.count(self._data)
    for i = 1, count do 
        local go = self.Root.transform:Find("reward"..i)
        if not go then
            if IsNull(self.loader) then
                self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/FightReady/FightRewardNode.prefab", nil, true)
            end
            if self.loader.IsSuccess then
                go = CfUtils.InstantiateGo(self.loader.ResultObject, self.Root)
            end
            if go then
                go.name = "reward"..i
            end
        end
        local scr = CfUtils.GetLuaScr(go, UIFightRewardNode)
        if scr then
            local itemGo = scr:RefreshNormal(checkTable(self._data[i]), self._size, self._isFillTitle)
            scr = CfUtils.GetLuaScr(itemGo, "Game.Behaviours.GoodNodeMB")
            if scr then
                local goodsId = self._data[i].goodsId or self._data[i].id
                local itemData = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                scr:SetClickCallback(function()
                    if itemData then
                        GameUtils.ShowCommonTipsBoard(itemGo, itemData.name, itemData.desc, itemData.quality, itemData.id)
                    end
                end)
            end
        end
    end

    local childCount = self.Root.transform.childCount
    if count < childCount then
        for i = count + 1, childCount do
            local go = self.Root.transform:Find("reward"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

function UIFightReardsNode:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release()
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightReardsNode
